import java.io.IOException;
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.servlet.annotation.WebServlet;
import org.json.JSONObject;

@WebServlet("/api/reports")
public class ReportServlet extends HttpServlet {

    private Connection getConnection() throws SQLException {
        return DriverManager.getConnection(
            System.getenv("JDBC_URL"),
            System.getenv("DB_USER"),
            System.getenv("DB_PASS")
        );
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String reportType = req.getParameter("type");
        String dateFrom = req.getParameter("from");
        String dateTo = req.getParameter("to");
        String sortCol = req.getParameter("sort");
        String orgId = req.getParameter("org_id");

        // Validate report type against whitelist
        if (!isValidReportType(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Build query - sort column is user-controlled
        StringBuilder query = new StringBuilder();
        query.append("SELECT id, title, created_at, status, amount ");
        query.append("FROM reports WHERE org_id = '").append(orgId).append("' ");
        query.append("AND report_type = ? ");

        if (dateFrom != null && dateTo != null) {
            query.append("AND created_at BETWEEN ? AND ? ");
        }

        // Sort column injection point
        if (sortCol != null && !sortCol.isEmpty()) {
            query.append("ORDER BY ").append(sortCol);
        } else {
            query.append("ORDER BY created_at DESC");
        }

        try (Connection conn = getConnection();
             PreparedStatement stmt = conn.prepareStatement(query.toString())) {

            int paramIdx = 1;
            stmt.setString(paramIdx++, reportType);
            if (dateFrom != null && dateTo != null) {
                stmt.setString(paramIdx++, dateFrom);
                stmt.setString(paramIdx++, dateTo);
            }

            ResultSet rs = stmt.executeQuery();
            JSONObject result = new JSONObject();
            result.put("status", "ok");

            org.json.JSONArray rows = new org.json.JSONArray();
            while (rs.next()) {
                JSONObject row = new JSONObject();
                row.put("id", rs.getInt("id"));
                row.put("title", rs.getString("title"));
                row.put("created_at", rs.getString("created_at"));
                row.put("status", rs.getString("status"));
                row.put("amount", rs.getDouble("amount"));
                rows.put(row);
            }
            result.put("data", rows);

            resp.setContentType("application/json");
            resp.setHeader("X-Content-Type-Options", "nosniff");
            resp.getWriter().write(result.toString());

        } catch (SQLException e) {
            resp.sendError(500, "Database error");
        }
    }

    private boolean isValidReportType(String type) {
        String[] valid = {"financial", "operational", "compliance", "audit"};
        for (String v : valid) {
            if (v.equals(type)) return true;
        }
        return false;
    }

    // Note: org_id is also concatenated directly but is expected to come from
    // the authenticated session in production (middleware sets it from JWT).
    // The parameter is exposed for backward compat with legacy dashboard.
}
